//   npx tsx prisma/demo.ts

import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "../generated/prisma/client";

// Prisma 7: the client is given a driver adapter. The connection URL is no
// longer read from schema.prisma.
const adapter = new PrismaBetterSqlite3({ url: process.env.DATABASE_URL ?? "file:./dev.db" });
const prisma = new PrismaClient({ adapter });

async function main() {
  await prisma.post.deleteMany();
  await prisma.user.deleteMany();

  // CREATE, with a nested create: the user and their posts in one call
  const user = await prisma.user.create({
    data: {
      email: "nadia@example.com",
      name: "Nadia",
      posts: { create: [{ title: "First post" }, { title: "Second post", published: true }] },
    },
    include: { posts: true },
  });
  console.log("created:", JSON.stringify(user));

  // READ, with a relation loaded through include
  const published = await prisma.user.findMany({
    where: { posts: { some: { published: true } } },
    include: { posts: { where: { published: true } } },
  });
  console.log("users with a published post:", published.length);

  // UPDATE
  const updated = await prisma.user.update({ where: { id: user.id }, data: { name: "Nadia K." } });
  console.log("updated name:", updated.name);

  // A unique constraint violation surfaces as an error with code P2002
  try {
    await prisma.user.create({ data: { email: "nadia@example.com" } });
  } catch (err) {
    console.log("duplicate email error code:", err.code); // expected: P2002
  }

  // DELETE: posts first, so no post is left pointing at a user that no longer exists
  await prisma.post.deleteMany({ where: { authorId: user.id } });
  await prisma.user.delete({ where: { id: user.id } });
  console.log("remaining users:", await prisma.user.count());
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
